"use strict";
// tests/unit/look-salon.test.js — owner wording 2026-11-13 (CLAUDE.md "Look suggestions" on claude-md-ops): the tool's own
// suggestions never name or recommend a procedure (tattooing, microblading / semi-permanent pigment, injections, thread lifts,
// laser, surgery) or skin-whitening; salons that do semi-permanent brows are customers, so a SALON'S OWN catalogue item name
// (entered by the salon in the back office) may name its method, shown as the salon's text, labelled as the salon's, never
// generated by us. FIXED TEST SET: written and hash-locked (~/LENSIQ-field/evals/beauty-look/locked.sha256 and
// evals-locks/beauty-look.sha256) BEFORE the salon parts of lensiq-look.js / lensiq-look-lint.js were written.
//
//   S1 generated wording: procedure words are banned (default lint)
//   S2 salon text (lintLook(text, {source: "salon"})): the procedure code alone is lifted; whitening, negative, score,
//      threat and every Merit code (purchase, price, link, ...) still apply
//   S3 salonItem(): a catalogue entry becomes an item with source "salon" and the fixed salon label (TH / EN / ZH);
//      entries failing S2 are refused
//   S4 salonHTML(): the salon's text is escaped and labelled; our own wrapper text passes the strict (generated) lint
//   S5 html() (generated items) drops any item whose wording fails the strict lint; suggest() never returns salon items
const test = require("node:test");
const assert = require("node:assert/strict");
const look = () => require("../../lensiq-look.js");
const lint = () => require("../../lensiq-look-lint.js");
const LANGS = ["th", "en", "zh"];
const SALON_LABEL = { th: "ข้อความของร้าน ไม่ใช่คำแนะนำของ LENSIQ", en: "The salon's own text, not a LENSIQ suggestion", zh: "店家自己的文字，并非 LENSIQ 的建议" };
const cls = { brow: { cat: "straight" }, eye: { cat: "soft" }, nose: { cat: "balanced" }, mouth: { cat: "small", note: "level" }, yintang: { cat: "balanced" },
  chin: { cat: "pointed" }, zones: { dominant: null } };

test("S1 generated wording: procedure words are banned", () => {
  for (const t of ["สักคิ้วลายเส้น 6D", "Microblading brow", "纹眉", "ทำคิ้วแบบกึ่งถาวร", "semi-permanent liner"]) {
    assert.ok(lint().lintLook(t).some(h => h.code === "procedure"), t);
  }
});

test("S2 salon text: only the procedure code is lifted; other bans still apply", () => {
  const L = lint();
  for (const t of ["สักคิ้วลายเส้น 6D", "Microblading — soft arch", "雾眉 柳叶形", "ทำคิ้วแบบกึ่งถาวร ทรงโค้ง"]) {
    assert.deepEqual(L.lintLook(t, { source: "salon" }), [], "salon may name its method: " + t);
  }
  const still = [["สักคิ้วลายเส้น ทำแล้วผิวขาว", "whitening"], ["Microblading for your flawed brows", "negative"], ["สักปากแล้วสวยขึ้น", "score"],
    ["สักคิ้ว ราคา 2,999 บาท", "price"], ["纹眉 立即购买", "purchase"], ["microblading www.example.com", "link"], ["สักคิ้ว ไม่งั้นโชคจะหาย", "threat"],
    ["雾眉 显白", "whitening"], ["permanent makeup guaranteed", "guarantee"]];
  for (const [t, code] of still) assert.ok(L.lintLook(t, { source: "salon" }).some(h => h.code === code), t + " -> " + code);
});

test("S3 salonItem(): salon source and the fixed salon label; refused when the text fails the salon lint", () => {
  const L = look();
  for (const l of LANGS) assert.equal(L.SALON_LABEL[l], SALON_LABEL[l], l);
  const entry = { id: "s1", kind: "brow", shape: "brow-arch", name: { th: "สักคิ้วลายเส้น ทรงโค้งนุ่ม", en: "Hair-stroke microblading, soft arch", zh: "线条雾眉 柔和弯眉" } };
  for (const l of LANGS) {
    const r = L.salonItem(entry, l);
    assert.equal(r.ok, true, l);
    assert.equal(r.item.source, "salon");
    assert.equal(r.item.label, SALON_LABEL[l]);
    assert.equal(r.item.text, entry.name[l]);
  }
  const bad = L.salonItem({ id: "s2", kind: "lip", shape: "lip-warm", name: { th: "สักปาก ผิวขาวขึ้น", en: "Lip blush that whitens skin", zh: "纹唇 显白" } }, "th");
  assert.equal(bad.ok, false);
  assert.ok(bad.errors.some(e => e.code === "whitening"));
});

test("S4 salonHTML(): escaped, labelled; our wrapper wording passes the strict lint", () => {
  const L = look();
  const it = L.salonItem({ id: "s3", kind: "brow", shape: "brow-arch", name: { th: "<b>สักคิ้ว</b> & ทรงโค้ง", en: "x", zh: "x" } }, "th").item;
  const h = L.salonHTML([it], "th");
  assert.ok(h.includes(SALON_LABEL.th) && /&lt;b&gt;/.test(h) && /&amp;/.test(h) && !/<b>สักคิ้ว/.test(h));
  assert.match(h, /data-lq-look/);
  for (const l of LANGS) for (const v of Object.values(L.SALON_TEXT[l])) assert.deepEqual(lint().lintLook(v), [], l + ": " + v);
});

test("S5 generated items: html() drops procedure wording; suggest() never returns salon items", () => {
  const L = look();
  const good = { id: "g", cat: "brows", reading: "คิ้วตรง", text: "ลองเติมกลางคิ้วให้โค้งขึ้นเล็กน้อย", label: L.LABEL.th, card: null, preview: null };
  const bad = { id: "b", cat: "brows", reading: "คิ้วตรง", text: "ลองสักคิ้วทรงโค้ง", label: L.LABEL.th, card: null, preview: null };
  const h = L.html([good, bad], "th");
  assert.ok(h.includes('data-look-id="g"') && !h.includes('data-look-id="b"'), "procedure item dropped");
  const salonish = Object.assign({}, bad, { source: "salon" });
  assert.ok(!L.html([salonish], "th").includes('data-look-id="b"'), "html() for generated items never accepts a salon flag");
  for (const l of LANGS) for (const i of L.suggest(cls, { el: "fire", lang: l })) assert.ok(i.source !== "salon");
});
